import torch, statistics, time
from torch.utils.cpp_extension import load_inline
cu = r'''
#include <cuda_runtime.h>
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
__device__ __forceinline__ unsigned long long gtm(){unsigned long long t; asm volatile("mov.u64 %0, %%globaltimer;":"=l"(t)); return t;}
__device__ __forceinline__ unsigned crank(){unsigned r; asm volatile("mov.u32 %0, %%cluster_ctarank;":"=r"(r)); return r;}
__device__ __forceinline__ void csync(){asm volatile("barrier.cluster.arrive.release.aligned;\n\tbarrier.cluster.wait.acquire.aligned;":::"memory");}
// ROUTE 3: hybrid, mates with dist 1..NL via L2, rest via DSMEM; ROUTE 4: null (barrier only); ROUTE 5: DSMEM push (st.shared::cluster into owner's recv buffer)
template<int KS,int NP,int ROUTE,int NL>
__global__ void __launch_bounds__(512,1) xk(float* scratch, unsigned long long* st, float* sink){
  extern __shared__ __align__(1024) float sm[];
  const int tid=threadIdx.x; const int r=(int)crank(); const int cid=blockIdx.x/KS;
  constexpr int TOT4=128*NP/4;
  float4* sm4=(float4*)sm;
  for(int i=tid;i<TOT4;i+=512) sm4[i]=make_float4(i*1e-3f,(float)r,(float)cid,1.f);
  auto lo_of=[&](int rr){return 128*rr/KS;};
  const int q0=lo_of(r)*NP/4, q1=lo_of(r+1)*NP/4;
  __syncthreads(); csync();
  unsigned long long t0=gtm();
  float acc=0.f;
  if(ROUTE==3){
    float4* my=(float4*)(scratch+(size_t)blockIdx.x*128*NP);
    // write rows owned by owners o with dist (r - o) mod KS in 1..NL  (o pulls from me via L2)
    for(int i=tid;i<TOT4;i+=512){ int row=i/(NP/4); int o=(row*KS)/128; while(lo_of(o+1)<=row) o++; while(lo_of(o)>row) o--; int dist=(r-o+KS)%KS; if(dist>=1&&dist<=NL) __stcg(my+i, sm4[i]); }
    csync();
    const float4* cb=(const float4*)(scratch+(size_t)cid*KS*128*NP);
    unsigned base=(unsigned)__cvta_generic_to_shared(sm);
    for(int q=q0+tid;q<q1;q+=512){ float4 s=sm4[q];
#pragma unroll
      for(int d=1;d<KS;d++){ int m=(r+d)%KS; float4 v;
        if(d<=NL) v=__ldcg(cb+(size_t)m*TOT4+q);
        else { unsigned ra; asm volatile("mapa.shared::cluster.u32 %0, %1, %2;":"=r"(ra):"r"(base+q*16),"r"(m));
          asm volatile("ld.shared::cluster.v4.f32 {%0,%1,%2,%3}, [%4];":"=f"(v.x),"=f"(v.y),"=f"(v.z),"=f"(v.w):"r"(ra)); }
        s.x+=v.x; s.y+=v.y; s.z+=v.z; s.w+=v.w; }
      acc+=s.x+s.y+s.z+s.w; }
  } else if(ROUTE==4){
    csync();
  } else if(ROUTE==5){
    // push: recv buffer after partial: [KS-1 slots][maxrows][NP]
    float4* recv=sm4+TOT4;
    constexpr int MR=(128+KS-1)/KS;
    unsigned rbase=(unsigned)__cvta_generic_to_shared(recv);
    for(int i=tid;i<TOT4;i+=512){ int row=i/(NP/4); int o=(row*KS)/128; while(lo_of(o+1)<=row) o++; while(lo_of(o)>row) o--; if(o==r) continue;
      int slot=(r-o+KS)%KS-1; int li=(row-lo_of(o))*(NP/4)+(i%(NP/4));
      unsigned ra; asm volatile("mapa.shared::cluster.u32 %0, %1, %2;":"=r"(ra):"r"(rbase+(slot*MR*(NP/4)+li)*16),"r"(o));
      float4 v=sm4[i]; asm volatile("st.shared::cluster.v4.f32 [%0], {%1,%2,%3,%4};"::"r"(ra),"f"(v.x),"f"(v.y),"f"(v.z),"f"(v.w):"memory"); }
    csync();
    for(int q=q0+tid;q<q1;q+=512){ float4 s=sm4[q]; int li=q-q0;
#pragma unroll
      for(int sl=0;sl<KS-1;sl++){ float4 v=recv[sl*MR*(NP/4)+li]; s.x+=v.x; s.y+=v.y; s.z+=v.z; s.w+=v.w; }
      acc+=s.x+s.y+s.z+s.w; }
  }
  __syncthreads();
  unsigned long long t1=gtm();
  if(tid==0){ st[blockIdx.x*2]=t0; st[blockIdx.x*2+1]=t1; }
  if(acc==123.f) sink[0]=acc;
  csync();
}
template<int KS,int NP,int R,int NL> int lau(torch::Tensor scratch, torch::Tensor st, torch::Tensor sink, int smem, int grid){
  auto k = xk<KS,NP,R,NL>;
  cudaFuncSetAttribute(k, cudaFuncAttributeMaxDynamicSharedMemorySize, smem);
  cudaLaunchConfig_t cfg={}; cfg.gridDim=dim3(grid); cfg.blockDim=dim3(512); cfg.dynamicSmemBytes=smem; cfg.stream=at::cuda::getCurrentCUDAStream();
  cudaLaunchAttribute at[2]; at[0].id=cudaLaunchAttributeClusterDimension; at[0].val.clusterDim.x=KS; at[0].val.clusterDim.y=1; at[0].val.clusterDim.z=1;
  at[1].id=cudaLaunchAttributeCooperative; at[1].val.cooperative=1;
  cfg.attrs=at; cfg.numAttrs=2;
  return (int)cudaLaunchKernelEx(&cfg, k, scratch.data_ptr<float>(), (unsigned long long*)st.data_ptr<int64_t>(), sink.data_ptr<float>());
}
int run(int id, torch::Tensor a, torch::Tensor c, torch::Tensor d){
  switch(id){
   case 0: return lau<6,100,4,0>(a,c,d,210*1024,132);
   case 1: return lau<6,100,3,2>(a,c,d,210*1024,132);
   case 2: return lau<6,100,3,3>(a,c,d,210*1024,132);
   case 3: return lau<6,100,5,0>(a,c,d,210*1024,132);
   case 4: return lau<4,100,3,1>(a,c,d,210*1024,132);
   case 5: return lau<4,100,3,2>(a,c,d,210*1024,132);
   case 6: return lau<4,100,5,0>(a,c,d,210*1024,132);
   case 7: return lau<3,196,3,1>(a,c,d,210*1024,132);
   case 8: return lau<3,196,5,0>(a,c,d,210*1024,132);
   case 9: return lau<3,196,4,0>(a,c,d,210*1024,132);
  }
  return -1;
}
'''
cpp = "int run(int,torch::Tensor,torch::Tensor,torch::Tensor);"
m = load_inline("xch4", cpp_sources=cpp, cuda_sources=cu, functions=["run"], extra_cuda_cflags=["-O3","-gencode=arch=compute_100a,code=sm_100a"], verbose=False)
scratch=torch.empty(148*128*392,device='cuda')
st=torch.zeros(400,dtype=torch.int64,device='cuda'); sink=torch.zeros(4,device='cuda')
flush=torch.empty(int(256e6)//4,device='cuda')
names=["KS6 N98 null(barrier)","KS6 N98 hybrid L2x2+DSMx3","KS6 N98 hybrid L2x3+DSMx2","KS6 N98 DSMEM push","KS4 N98 hybrid L2x1+DSMx2","KS4 N98 hybrid L2x2+DSMx1","KS4 N98 DSMEM push","KS3 N196 hybrid L2x1+DSMx1","KS3 N196 DSMEM push","KS3 N196 null"]
for i,nm in enumerate(names):
    meds=[];mxs=[]
    for rep in range(6):
        flush.zero_(); torch.cuda.synchronize()
        e=m.run(i,scratch,st,sink); torch.cuda.synchronize()
        if e!=0: print("err",nm,e); break
        s=st[:264].view(132,2).cpu(); d=((s[:,1]-s[:,0]).double()/1000).tolist()
        if rep>0: meds.append(statistics.median(d)); mxs.append(max(d))
    if meds: print(nm, "median %.2f us max %.2f"%(statistics.median(meds), statistics.median(mxs)))

